def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    for r in range(h):
        for c1 in range(w):
            for c2 in range(c1 + 1, w):
                if grid[r][c1] == grid[r][c2] != bg:
                    for c in range(c1 + 1, c2):
                        if grid[r][c] == bg: out[r][c] = 3
    for c in range(w):
        for r1 in range(h):
            for r2 in range(r1 + 1, h):
                if grid[r1][c] == grid[r2][c] != bg:
                    for r in range(r1 + 1, r2):
                        if grid[r][c] == bg: out[r][c] = 3
    return out
